import { defaultKeymap, history, historyKeymap, indentWithTab, redo, undo } from "@codemirror/commands";
import { javascript } from "@codemirror/lang-javascript";
import { json } from "@codemirror/lang-json";
import { markdown } from "@codemirror/lang-markdown";
import { yaml } from "@codemirror/lang-yaml";
import { bracketMatching, defaultHighlightStyle, indentOnInput, syntaxHighlighting, syntaxTree } from "@codemirror/language";
import { Compartment, EditorState } from "@codemirror/state";
import {
  crosshairCursor,
  drawSelection,
  dropCursor,
  EditorView,
  highlightActiveLine,
  highlightActiveLineGutter,
  highlightSpecialChars,
  keymap,
  lineNumbers,
  rectangularSelection,
  Decoration,
  ViewPlugin,
} from "@codemirror/view";
import { oneDark } from "@codemirror/theme-one-dark";
import { highlightSelectionMatches, searchKeymap } from "@codemirror/search";

const languageCompartment = new Compartment();
const editableCompartment = new Compartment();
const lineWrappingCompartment = new Compartment();
const fontSizeCompartment = new Compartment();
const themeCompartment = new Compartment();

function atlasSyntaxHighlighting(dark) {
  return [syntaxHighlighting(defaultHighlightStyle, { fallback: true })];
}

const yamlValueHighlighting = ViewPlugin.fromClass(class {
  constructor(view) {
    this.decorations = this.build(view);
  }

  update(update) {
    if (update.docChanged || update.viewportChanged || update.transactions.length) {
      this.decorations = this.build(update.view);
    }
  }

  build(view) {
    const source = view.state.doc.toString();
    const decorations = [];
    const tree = syntaxTree(view.state);
    tree.iterate({
      enter(node) {
        if (node.name === "Comment") {
          decorations.push(Decoration.mark({ class: "cm-atlas-yaml-comment" }).range(node.from, node.to));
        }

        const isKey = node.node.parent?.name === "Key";
        if (node.name === "QuotedLiteral" && !isKey) {
          decorations.push(Decoration.mark({ class: "cm-atlas-yaml-string" }).range(node.from, node.to));
        }

        if ((node.name === "Literal" || node.name === "QuotedLiteral") && !isKey) {
          const quoted = node.name === "QuotedLiteral";
          const rawValue = source.slice(node.from, node.to);
          const value = (quoted ? rawValue.slice(1, -1) : rawValue).trim();
          const valueFrom = node.from + (quoted ? 1 : 0);
          const valueTo = node.to - (quoted ? 1 : 0);
          const className = /^true$/i.test(value)
            ? "cm-atlas-yaml-true"
            : /^false$/i.test(value)
              ? "cm-atlas-yaml-false"
              : /^unknown$/i.test(value)
                ? "cm-atlas-yaml-unknown"
                : !quoted && /^[+-]?(?:0x[\da-f_]+|0o[0-7_]+|0b[01_]+|(?:\d[\d_]*\.?[\d_]*|\.\d[\d_]*)(?:e[+-]?\d[\d_]*)?)$/i.test(value)
                  ? "cm-atlas-yaml-number"
                : null;
          if (className) decorations.push(Decoration.mark({ class: className }).range(valueFrom, valueTo));
        }

        if (node.name === "BlockLiteralContent") {
          const pair = node.node.parent?.parent;
          const key = pair?.getChild("Key");
          if (!key || source.slice(key.from, key.to).trim().toLowerCase() !== "query") return;
          const block = source.slice(node.from, node.to);
          const sqlKeyword = /\b(?:SELECT|FROM|WHERE|ROUND|SUM|AS|JOIN|LEFT|RIGHT|INNER|OUTER|ON|GROUP|BY|ORDER|LIMIT|CASE|WHEN|THEN|ELSE|END|DISTINCT|COUNT|AVG|MIN|MAX|AND|OR|NOT|IN|IS|NULL|LIKE)\b/g;
          let match;
          while ((match = sqlKeyword.exec(block))) {
            const from = node.from + match.index;
            decorations.push(Decoration.mark({ class: "cm-atlas-sql-keyword" }).range(from, from + match[0].length));
          }
        }
      },
    });
    return Decoration.set(decorations.sort((left, right) => left.from - right.from));
  }
}, { decorations: value => value.decorations });

const templateStringHighlighting = ViewPlugin.fromClass(class {
  constructor(view) {
    this.decorations = this.build(view);
  }

  update(update) {
    if (update.docChanged) this.decorations = this.build(update.view);
  }

  build(view) {
    const source = view.state.doc.toString();
    const decorations = [];
    const templateExpression = /\{\{([\s\S]*?)\}\}/g;
    let expression;

    while ((expression = templateExpression.exec(source))) {
      decorations.push(Decoration.mark({ class: "cm-atlas-template-delimiter" }).range(expression.index, expression.index + 2));
      decorations.push(Decoration.mark({ class: "cm-atlas-template-delimiter" }).range(templateExpression.lastIndex - 2, templateExpression.lastIndex));
      const body = expression[1];
      const bodyStart = expression.index + 2;
      const stringToken = /"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'/g;
      const stringRanges = [];
      let stringMatch;
      while ((stringMatch = stringToken.exec(body))) {
        const from = bodyStart + stringMatch.index;
        const to = from + stringMatch[0].length;
        stringRanges.push([from, to]);
        decorations.push(Decoration.mark({ class: "cm-atlas-template-string" }).range(from, to));
      }

      const templateFunction = /\b(?:states|float|map|round)\b/gi;
      let functionMatch;
      while ((functionMatch = templateFunction.exec(body))) {
        const from = bodyStart + functionMatch.index;
        const to = from + functionMatch[0].length;
        if (stringRanges.some(([stringFrom, stringTo]) => from < stringTo && to > stringFrom)) continue;
        decorations.push(Decoration.mark({ class: "cm-atlas-template-function" }).range(from, to));
      }

      const numberToken = /\b\d+(?:\.\d+)?\b/g;
      let numberMatch;
      while ((numberMatch = numberToken.exec(body))) {
        const from = bodyStart + numberMatch.index;
        const to = from + numberMatch[0].length;
        if (stringRanges.some(([stringFrom, stringTo]) => from < stringTo && to > stringFrom)) continue;
        decorations.push(Decoration.mark({ class: "cm-atlas-template-number" }).range(from, to));
      }
    }

    return Decoration.set(decorations.sort((left, right) => left.from - right.from));
  }
}, { decorations: value => value.decorations });

function extensionLanguage(extension) {
  const normalizedExtension = String(extension ?? "").trim().toLowerCase();
  if (["yaml", "yml"].includes(normalizedExtension)) return [yaml(), yamlValueHighlighting];
  if (normalizedExtension === "json") return json();
  if (["js", "mjs", "ts"].includes(normalizedExtension)) return javascript({ typescript: normalizedExtension === "ts" });
  if (["md", "markdown"].includes(normalizedExtension)) return markdown();
  return [];
}

function createAtlasLightTheme(fontSize) {
  return [EditorView.theme({
    "&": {
      height: "100%",
      minHeight: "100%",
      fontSize: `${fontSize}px`,
      backgroundColor: "var(--atlas-panel-soft)",
      color: "var(--atlas-text)",
    },
    ".cm-scroller": {
      fontFamily: '"Cascadia Code", "SFMono-Regular", Consolas, monospace',
      lineHeight: "1.55",
    },
    ".cm-content": {
      minHeight: "100%",
      caretColor: "var(--atlas-accent)",
    },
    ".cm-atlas-template-string": { color: "#7e22ce" },
    ".cm-atlas-template-number": { color: "#9a3412" },
    ".cm-atlas-template-delimiter": { color: "#374151" },
    ".cm-atlas-template-function": { color: "#c2410c" },
    ".cm-atlas-yaml-comment": { color: "#008f87" },
    ".cm-atlas-yaml-string": { color: "#16803c" },
    ".cm-atlas-yaml-number": { color: "#9a3412" },
    ".cm-atlas-yaml-true": { color: "#16803c", fontWeight: "600" },
    ".cm-atlas-yaml-false": { color: "#c62828", fontWeight: "600" },
    ".cm-atlas-yaml-unknown": { color: "#b45309", fontWeight: "600" },
    ".cm-atlas-sql-keyword": { color: "#7c3aed", fontWeight: "600" },
    ".cm-gutters": {
      backgroundColor: "var(--atlas-panel)",
      borderRight: "1px solid var(--atlas-border)",
      color: "var(--atlas-muted)",
    },
    ".cm-activeLine, .cm-activeLineGutter": {
      backgroundColor: "var(--atlas-accent-soft)",
    },
    "&.cm-focused": {
      outline: "2px solid color-mix(in srgb, var(--atlas-accent) 30%, transparent)",
    },
  }, { dark: false }),
  atlasSyntaxHighlighting(false),
  ];
}

function createAtlasDarkTheme(fontSize) {
  return [
    oneDark,
    EditorView.theme({
      "&": {
        height: "100%",
        minHeight: "100%",
        fontSize: `${fontSize}px`,
        backgroundColor: "var(--atlas-panel-soft)",
        color: "var(--atlas-text)",
      },
      ".cm-scroller": {
        fontFamily: '"Cascadia Code", "SFMono-Regular", Consolas, monospace',
        lineHeight: "1.55",
      },
      ".cm-gutters": {
        backgroundColor: "var(--atlas-panel)",
        borderRight: "1px solid var(--atlas-border)",
        color: "var(--atlas-muted)",
      },
      ".cm-atlas-template-string": { color: "#f0abfc" },
      ".cm-atlas-template-number": { color: "#ffffff" },
      ".cm-atlas-template-delimiter": { color: "#ffffff" },
      ".cm-atlas-template-function": { color: "#ffd54f" },
      ".cm-atlas-yaml-comment": { color: "#4dd0e1" },
      ".cm-atlas-yaml-string": { color: "#81c784" },
      ".cm-atlas-yaml-number": { color: "#ffffff" },
      ".cm-atlas-yaml-true": { color: "#81c784", fontWeight: "600" },
      ".cm-atlas-yaml-false": { color: "#ff8a80", fontWeight: "600" },
      ".cm-atlas-yaml-unknown": { color: "#ffb74d", fontWeight: "600" },
      ".cm-atlas-sql-keyword": { color: "#ce93d8", fontWeight: "600" },
      ".cm-activeLine, .cm-activeLineGutter": {
        backgroundColor: "var(--atlas-accent-soft)",
      },
    }, { dark: true }),
    atlasSyntaxHighlighting(true),
  ];
}

function themeExtension(fontSize) {
  return document.documentElement.dataset.theme === "dark"
    ? createAtlasDarkTheme(fontSize)
    : createAtlasLightTheme(fontSize);
}

function createEditor(host, options = {}) {
  const onChange = typeof options.onChange === "function" ? options.onChange : () => {};
  const onCursor = typeof options.onCursor === "function" ? options.onCursor : () => {};
  let currentFontSize = Number.isFinite(options.fontSize) ? options.fontSize : 14;

  const view = new EditorView({
    parent: host,
    state: EditorState.create({
      doc: options.content ?? "",
      extensions: [
        lineNumbers(),
        highlightActiveLineGutter(),
        highlightSpecialChars(),
        history(),
        drawSelection(),
        dropCursor(),
        indentOnInput(),
        templateStringHighlighting,
        bracketMatching(),
        rectangularSelection(),
        crosshairCursor(),
        highlightActiveLine(),
        highlightSelectionMatches(),
        keymap.of([...defaultKeymap, ...historyKeymap, ...searchKeymap, indentWithTab]),
        languageCompartment.of(extensionLanguage(options.extension)),
        editableCompartment.of(EditorView.editable.of(options.readonly !== true)),
        lineWrappingCompartment.of(options.wordWrap === false ? [] : EditorView.lineWrapping),
        fontSizeCompartment.of(EditorView.theme({
          "&": { fontSize: `${currentFontSize}px` },
        })),
        themeCompartment.of(themeExtension(currentFontSize)),
        EditorView.updateListener.of(update => {
          if (update.docChanged) {
            onChange();
          }
          if (update.selectionSet || update.docChanged) {
            onCursor(getCursorPosition(view));
          }
        }),
      ],
    }),
  });

  return {
    getValue() {
      return view.state.doc.toString();
    },
    setValue(value) {
      view.dispatch({
        changes: {
          from: 0,
          to: view.state.doc.length,
          insert: value ?? "",
        },
      });
    },
    setReadOnly(readonly) {
      view.dispatch({
        effects: editableCompartment.reconfigure(EditorView.editable.of(readonly !== true)),
      });
    },
    setLanguage(extension) {
      view.dispatch({
        effects: languageCompartment.reconfigure(extensionLanguage(extension)),
      });
    },
    setWordWrap(wordWrap) {
      view.dispatch({
        effects: lineWrappingCompartment.reconfigure(wordWrap === false ? [] : EditorView.lineWrapping),
      });
    },
    setFontSize(fontSize) {
      currentFontSize = fontSize;
      view.dispatch({
        effects: fontSizeCompartment.reconfigure(EditorView.theme({
          "&": { fontSize: `${fontSize}px` },
        })),
      });
    },
    refreshTheme() {
      view.dispatch({
        effects: themeCompartment.reconfigure(themeExtension(currentFontSize)),
      });
    },
    cursorPosition() {
      return getCursorPosition(view);
    },
    undo() {
      return undo(view);
    },
    redo() {
      return redo(view);
    },
    focus() {
      view.focus();
    },
  };
}

function getCursorPosition(view) {
  const head = view.state.selection.main.head;
  const line = view.state.doc.lineAt(head);
  return {
    line: line.number,
    column: head - line.from + 1,
  };
}

window.AtlasFileStudioEditor = {
  create: createEditor,
};

:root {
  color-scheme: light;
  font-family: system-ui, sans-serif;
  --atlas-bg: #f5f7fb;
  --atlas-panel: #ffffff;
  --atlas-panel-soft: #f8fafc;
  --atlas-text: #172033;
  --atlas-muted: #536079;
  --atlas-placeholder: #6d7d91;
  --atlas-border: #d8e0ec;
  --atlas-border-soft: #cbd5e1;
  --atlas-accent: #0f766e;
  --atlas-accent-strong: #115e59;
  --atlas-accent-soft: #e6fffb;
  --atlas-link: #0f766e;
  --atlas-folder: #d97706;
  --atlas-file: #0891b2;
  --atlas-file-yaml: #e11d48;
  --atlas-file-json: #ca8a04;
  --atlas-file-code: #2563eb;
  --atlas-file-markdown: #7c3aed;
  --atlas-file-text: #64748b;
  --atlas-file-archive: #9333ea;
  --atlas-file-image: #16a34a;
  --atlas-on-accent: #ffffff;
  --atlas-danger-soft: #fee2e2;
  --atlas-danger-text: #991b1b;
  --tree-width: 300px;
  --folder-width: 360px;
  --studio-height: clamp(820px, calc(100vh - 240px), 1024px);
  --studio-width: min(100%, 1900px);
  --editor-font-size: 14px;
  --image-preview-width: 70vw;
  --image-preview-height: 70vh;
  background: var(--atlas-bg);
  color: var(--atlas-text);
}

:root[data-height-limit="off"] {
  --studio-height: max(820px, calc(100vh - 240px));
}

:root[data-width-limit="off"] {
  --studio-width: 100%;
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --atlas-bg: #0f1417;
  --atlas-panel: #171f23;
  --atlas-panel-soft: #11191d;
  --atlas-text: #f7fcfd;
  --atlas-muted: #c3d3d8;
  --atlas-placeholder: #d7e5ea;
  --atlas-border: #2f4046;
  --atlas-border-soft: #40535b;
  --atlas-accent: #2dd4bf;
  --atlas-accent-strong: #14b8a6;
  --atlas-accent-soft: #113c30;
  --atlas-link: #7ee6c9;
  --atlas-folder: #fbbf24;
  --atlas-file: #67e8f9;
  --atlas-file-yaml: #fb7185;
  --atlas-file-json: #facc15;
  --atlas-file-code: #60a5fa;
  --atlas-file-markdown: #c084fc;
  --atlas-file-text: #cbd5e1;
  --atlas-file-archive: #d8b4fe;
  --atlas-file-image: #86efac;
  --atlas-on-accent: #06201d;
  --atlas-danger-soft: #4b1717;
  --atlas-danger-text: #fecaca;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--atlas-bg);
  color: var(--atlas-text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.studio-shell {
  width: var(--studio-width);
  margin: 0 auto;
  padding: 24px;
}

.studio-header {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
}

.header-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
  gap: 8px;
}

.segmented-control {
  display: inline-flex;
  min-height: 34px;
  overflow: hidden;
  border: 1px solid var(--atlas-border);
  border-radius: 4px;
  background: var(--atlas-panel-soft);
}

.segmented-control button {
  min-height: 32px;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--atlas-muted);
  padding: 0 10px;
  font: inherit;
  font-size: 13px;
  font-weight: 800;
  cursor: pointer;
}

.segmented-control button:hover,
.segmented-control button:focus-visible {
  color: var(--atlas-link);
  outline: 0;
}

.segmented-control button[aria-pressed="true"] {
  background: var(--atlas-accent);
  color: var(--atlas-on-accent);
}

.eyebrow,
h1,
h2,
p {
  margin: 0;
}

.eyebrow {
  margin-bottom: 6px;
  color: var(--atlas-accent);
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0;
  text-transform: uppercase;
}

h1 {
  margin-bottom: 8px;
  font-size: 28px;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: 0;
}

h2 {
  font-size: 1rem;
  line-height: 1.2;
}

p {
  color: var(--atlas-muted);
  line-height: 1.5;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 34px;
  border: 1px solid var(--atlas-border);
  border-radius: 4px;
  background: var(--atlas-panel-soft);
  color: var(--atlas-link);
  padding: 7px 10px;
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  text-decoration: none;
}

.button:hover,
.button:focus-visible {
  border-color: var(--atlas-accent);
  background: var(--atlas-accent-soft);
  color: var(--atlas-link);
  outline: 0;
}

.button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.toggle-button.is-active {
  border-color: var(--atlas-accent);
  background: var(--atlas-accent);
  color: var(--atlas-on-accent);
}

.studio-grid {
  display: grid;
  grid-template-columns:
    minmax(210px, var(--tree-width))
    8px
    minmax(220px, var(--folder-width))
    8px
    minmax(420px, 1fr);
  gap: 0;
  align-items: stretch;
}

.file-tree,
.folder-panel,
.editor-panel {
  height: var(--studio-height);
  min-height: var(--studio-height);
  padding: 14px;
  border: 1px solid var(--atlas-border);
  border-radius: 6px;
  background: var(--atlas-panel);
  color: var(--atlas-text);
}

.file-tree {
  border-radius: 6px 0 0 6px;
}

.folder-panel {
  border-radius: 0;
}

.editor-panel {
  display: flex;
  flex-direction: column;
  min-width: 0;
  overflow: hidden;
  border-radius: 0 6px 6px 0;
}

.splitter {
  min-height: var(--studio-height);
  border-top: 1px solid var(--atlas-border);
  border-bottom: 1px solid var(--atlas-border);
  background:
    linear-gradient(90deg, transparent 0 3px, var(--atlas-border) 3px 5px, transparent 5px 8px);
  cursor: col-resize;
  touch-action: none;
}

.splitter:hover,
.splitter:focus-visible,
body.is-resizing .splitter {
  background:
    linear-gradient(90deg, transparent 0 2px, var(--atlas-accent) 2px 6px, transparent 6px 8px);
  outline: 0;
}

.panel-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.panel-heading span {
  color: var(--atlas-link);
  font-size: 0.9rem;
  font-weight: 800;
}

.tree-panel-heading {
  display: grid;
  align-items: start;
  justify-content: stretch;
  gap: 8px;
}

.tree-title-row {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.tree-title-row span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tree-heading-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-start;
  gap: 6px;
}

.icon-button {
  position: relative;
  width: 32px;
  height: 32px;
  border: 1px solid transparent;
  border-radius: 4px;
  background: transparent;
  color: var(--atlas-link);
  cursor: pointer;
}

.icon-button:hover,
.icon-button:focus-visible {
  border-color: var(--atlas-border);
  background: var(--atlas-panel-soft);
  outline: 0;
}

.icon-button::before,
.icon-button::after {
  content: "";
  position: absolute;
  box-sizing: border-box;
}

.icon-file-add::before {
  inset: 6px 10px 6px 8px;
  border: 1.5px solid currentColor;
  border-radius: 2px;
}

.icon-file-add::after,
.icon-folder-add::after {
  right: 5px;
  bottom: 5px;
  width: 9px;
  height: 9px;
  background:
    linear-gradient(currentColor 0 0) center / 9px 1.5px no-repeat,
    linear-gradient(currentColor 0 0) center / 1.5px 9px no-repeat;
}

.icon-folder-add::before {
  left: 5px;
  right: 8px;
  bottom: 7px;
  height: 11px;
  border-radius: 2px;
  background:
    linear-gradient(currentColor 0 0) left 2px top 0 / 9px 4px no-repeat,
    currentColor;
}

.icon-refresh::before {
  inset: 7px;
  border: 1.5px solid currentColor;
  border-right-color: transparent;
  border-radius: 999px;
}

.icon-refresh::after {
  right: 6px;
  top: 5px;
  width: 7px;
  height: 7px;
  border-top: 1.5px solid currentColor;
  border-right: 1.5px solid currentColor;
  transform: rotate(18deg);
}

.icon-collapse::before {
  inset: 7px 6px;
  border: 1.5px solid currentColor;
  border-radius: 2px;
}

.icon-collapse::after {
  left: 10px;
  right: 10px;
  top: 13px;
  height: 1.5px;
  background: currentColor;
}

.icon-close::before,
.icon-close::after {
  left: 7px;
  top: 13px;
  width: 12px;
  height: 2px;
  border-radius: 999px;
  background: currentColor;
}

.icon-close::before {
  transform: rotate(45deg);
}

.icon-close::after {
  transform: rotate(-45deg);
}

.icon-zoom-in::before,
.icon-zoom-out::before {
  inset: 6px;
  border: 2px solid currentColor;
  border-radius: 999px;
}

.icon-zoom-in::after,
.icon-zoom-out::after {
  left: 11px;
  top: 10px;
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background:
    linear-gradient(currentColor 0 0) center / 8px 2px no-repeat,
    transparent;
}

.icon-zoom-in::after {
  background:
    linear-gradient(currentColor 0 0) center / 8px 2px no-repeat,
    linear-gradient(currentColor 0 0) center / 2px 8px no-repeat;
}

.icon-zoom-reset::before {
  inset: 7px;
  border: 2px solid currentColor;
  border-radius: 3px;
}

.icon-zoom-reset::after {
  left: 10px;
  right: 10px;
  top: 13px;
  height: 2px;
  border-radius: 999px;
  background: currentColor;
}

.icon-star::before {
  inset: 6px;
  background: currentColor;
  clip-path: polygon(50% 0, 62% 34%, 98% 35%, 69% 56%, 80% 91%, 50% 70%, 20% 91%, 31% 56%, 2% 35%, 38% 34%);
