.svg-icon-button.icon-download::before { mask-image: url("icons/download.svg"); }
.svg-icon-button.icon-word-wrap::before { mask-image: url("icons/word-wrap.svg"); }
.svg-icon-button.icon-zoom-in::before { mask-image: url("icons/zoom-in.svg"); }
.svg-icon-button.icon-zoom-out::before { mask-image: url("icons/zoom-out.svg"); }
.svg-icon-button.icon-search::before { mask-image: url("icons/search.svg"); }
.svg-icon-button.icon-hidden::before { mask-image: url("icons/eye.svg"); }
.svg-icon-button.icon-rename::before { mask-image: url("icons/rename.svg"); }
.svg-icon-button.icon-copy::before { mask-image: url("icons/copy.svg"); }
.svg-icon-button.icon-move::before { mask-image: url("icons/move.svg"); }
.svg-icon-button.icon-delete::before { mask-image: url("icons/delete.svg"); }
