.archive-preview-empty {
  padding: 18px 14px;
  color: var(--atlas-muted);
}

.image-preview-resize-handle {
  position: absolute;
  right: 8px;
  bottom: 8px;
  z-index: 2;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 2px solid #f0645c;
  border-radius: 6px;
  background:
    linear-gradient(135deg, transparent 0 46%, #f0645c 47% 53%, transparent 54%),
    linear-gradient(135deg, transparent 0 64%, #f0645c 65% 71%, transparent 72%),
    #ffffff;
  box-shadow: 0 6px 14px rgba(23, 32, 51, 0.16);
  cursor: nwse-resize;
  touch-action: none;
}

.image-preview-resize-handle:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--atlas-accent) 35%, transparent);
  outline-offset: 3px;
}

.editor-input:focus {
  border-color: var(--atlas-accent);
  outline: 2px solid color-mix(in srgb, var(--atlas-accent) 30%, transparent);
}

.editor-input .cm-editor {
  height: 100%;
  min-height: 0;
  border-radius: 6px;
}

.editor-input .cm-scroller {
  height: 100%;
  overflow: auto;
}

.editor-input .cm-content {
  padding: 14px 0;
}

.editor-input .cm-line {
  padding: 0 14px;
}

.status-row {
  flex: 0 0 auto;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

.status-row span {
  border: 1px solid var(--atlas-border);
  border-radius: 999px;
  background: var(--atlas-panel-soft);
  color: var(--atlas-muted);
  padding: 6px 10px;
  font-size: 0.85rem;
  font-weight: 800;
}

.status-row .ok {
  border-color: var(--atlas-accent);
  background: var(--atlas-accent-soft);
  color: var(--atlas-link);
}

.status-row .warning {
  border-color: var(--atlas-danger-text);
  background: var(--atlas-danger-soft);
  color: var(--atlas-danger-text);
}

@media (max-width: 760px) {
  .studio-shell {
    padding: 18px 10px 28px;
  }

  .studio-header,
  .studio-grid {
    display: grid;
  }

  .studio-grid {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .file-tree,
  .folder-panel,
  .editor-panel {
    border-radius: 6px;
  }

  .splitter {
    display: none;
  }
}
